import{_ as i,b as o,c as n,l as s,d as e,k as t}from"./chunks/framework.Yp4hj_cn.js";const f=JSON.parse(`{"title":"Why?","description":"","frontmatter":{"head":[["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"Armaan Gomes"}],["meta",{"property":"og:title","content":"Why? — Armaan Gomes"}],["meta",{"property":"og:description","content":"Hi! I'm Armaan Gomes. I like to build things."}],["meta",{"property":"og:url","content":"https://armaangomes.com/claim"}],["meta",{"name":"twitter:card","content":"summary"}],["meta",{"name":"twitter:title","content":"Why? — Armaan Gomes"}],["meta",{"name":"twitter:description","content":"Hi! I'm Armaan Gomes. I like to build things."}]]},"headers":[],"relativePath":"claim.md","filePath":"claim.md"}`),l={name:"claim.md"};function r(d,a,h,m,c,p){return o(),n("div",null,[...a[0]||(a[0]=[s('<p><span class="headline">Claim the Stars</span></p><div style="height:40px;"></div><h1 id="why" tabindex="-1">Why? <a class="header-anchor" href="#why" aria-label="Permalink to “Why?”">​</a></h1><p>A few years ago, I learned how suddenly life could end. I suppose I always knew in theory, but experience is a bit harsher.</p><p>I realized that I didn&#39;t want to live life wondering what could&#39;ve been. I&#39;d rather fail infinitely chasing impossible dreams than play it safe for eternity.</p><p>If I&#39;m being honest, I consider myself a failure. Not in the doom and despair sense that I&#39;ll never achieve anything, but in that satistically most things I try to do fail. Right before writing this I failed to solder an IMU; It took me two weeks of straight failures to successfully read and write from DDR3; It took me over 200 tries to sucessfully read data from a singular PDM microphone. Frankly, I wouldn&#39;t have it any other way. A life without failure is monotonus</p><p>I try to live each day like it could be my last. Not that it is my last, but that if it were all end today, I could at rest easy knowing that I gave my all.</p><div class="accent"> I live each day with 3 goals. <ol><li>To live as me to the fullest</li><li>To lift up my friends</li><li>To keep building cool things</li></ol></div><div style="height:40px;"></div>',9),e("p",null,[e("span",{class:"newsreader"},[t("What if I'm not enough to "),e("span",{style:{"white-space":"nowrap"}},[e("a",{href:"https://www.youtube.com/watch?v=t2XgGSdMWSQ",onclick:"if(window.__playMusic){event.preventDefault();window.__playMusic('t2XgGSdMWSQ','Cold','Jeff Williams');}"},"Claim the Stars")]),t("? "),e("div",{style:{height:"10px"}}),t(),e("div",{class:"accent"},"What if I am?")])],-1),e("div",{style:{height:"60px"}},null,-1)])])}const u=i(l,[["render",r]]);export{f as __pageData,u as default};
